local({
  uk <- cbind(as.numeric(respondent_born_uk), as.numeric(respondent_born_uk_PARTNER))
  v <- case_when(
    rowSums(uk == 1, na.rm = TRUE) > 0 ~ "Native",
    rowSums(uk == 2, na.rm = TRUE) > 0 ~ "Second-generation",
    .default = NA_character_
  )
  coalesce(carry_within(v, participant_id, .wave), "Unknown")
})

local({
  items <- cbind(as.numeric(DPTVRL00), as.numeric(DPTVRH00))
  case_when(
    rowSums(items == 1, na.rm = TRUE) > 0 ~ "TRUE",
    rowSums(items == 2, na.rm = TRUE) > 0 ~ "FALSE",
    .default = NA_character_
  )
})

local({
  hurt <- coalesce(as.numeric(ECQ56X00), as.numeric(FCHURT00))
  case_when(
    as.numeric(DCSC0036) %in% c(1, 2) ~ "TRUE",
    as.numeric(DCSC0036) == 3 ~ "FALSE",
    hurt %in% c(1, 2, 3, 4, 5) ~ "TRUE",
    hurt == 6 ~ "FALSE"
  )
})

