local({
  ever <- coalesce(as.numeric(ECQ61X00), as.numeric(FCALCD00), as.numeric(GCALCD00))
  month <- coalesce(as.numeric(ECQ64X00), as.numeric(FCALNF00), as.numeric(GCALNF00))
  case_when(
    month %in% c(2, 3, 4, 5, 6, 7) ~ "TRUE",
    month == 1 ~ "FALSE",
    ever == 2 ~ "FALSE",
    .default = NA_character_
  )
})

local({
  onset <- recode_values(as.numeric(FCSLWK00), 1 ~ 21, 2 ~ 21.5, 3 ~ 22.5, 4 ~ 23.5, 5 ~ 24)
  wake <- recode_values(as.numeric(FCWUWK00), 1 ~ 6, 2 ~ 6.5, 3 ~ 7.5, 4 ~ 8.5, 5 ~ 9)
  wake + 24 - onset
})

local({
