    onset <- recode_values(as.numeric(FCSLWK00), 1 ~ 21, 2 ~ 21.5, 3 ~ 22.5, 4 ~ 23.5, 5 ~ 24)
    wake <- recode_values(as.numeric(FCWUWK00), 1 ~ 6, 2 ~ 6.5, 3 ~ 7.5, 4 ~ 8.5, 5 ~ 9)
    wake + 24 - onset
  }) +
  2 *
    local({
      onset <- recode_values(as.numeric(FCSLWE00), 1 ~ 21, 2 ~ 21.5, 3 ~ 22.5, 4 ~ 23.5, 5 ~ 24)
      wake <- recode_values(as.numeric(FCWUWE00), 1 ~ 8, 2 ~ 8.5, 3 ~ 9.5, 4 ~ 10.5, 5 ~ 11.5, 6 ~ 12)
